        $this->logDebug("Extract order for User personal api key");
        $span = $this->startSpan("Extract order for User personal api key");
        try {
            $mapped = [];
            foreach ($order as $ord) {
                if ($ord === 'name-asc') {
                    $mapped[] = 'nameAsc';
                }
                if ($ord === 'name-desc') {
                    $mapped[] = 'nameDesc';
                }
            }
            return $mapped;
